'use client'

import { useQuery } from '@tanstack/react-query'
import type { AgendaAppointment } from '@/app/api/dashboard/today-agenda/route'

export type { AgendaAppointment }

async function fetchTodayAgenda(): Promise<AgendaAppointment[]> {
  const res = await fetch('/api/dashboard/today-agenda')
  if (!res.ok) throw new Error('Failed to fetch today agenda')
  return res.json() as Promise<AgendaAppointment[]>
}

export function useTodayAgenda(enabled: boolean) {
  return useQuery({
    queryKey: ['dashboard', 'today-agenda'],
    queryFn: fetchTodayAgenda,
    enabled,
    staleTime: 60_000,
    retry: 1,
    placeholderData: [] as AgendaAppointment[],
  })
}

